      peoples: [["u3_barrio", "barrio"], ["u3_luz", "luz"], ["u3_fuego", "fuego"], ["u3_planta", "planta"], ["u3_altos", "altos"], ["u3_sombra", "sombra"], ["u3_agua", "agua"], ["u3_piedra", "piedra"], ["u3_escarcha", "escarcha"]],
